<div class="row g-3 vacancy-form"><div class="col-md-6"><label class="form-label">Puesto</label><input class="form-control" name="puesto" required></div><div class="col-md-6"><label class="form-label">Área</label><input class="form-control" name="area" required></div><div class="col-md-6"><label class="form-label">Ubicación</label><input class="form-control" name="ubicacion" required></div><div class="col-md-3"><label class="form-label">Modalidad</label><select class="form-select" name="modalidad"><option>Presencial</option><option>Híbrido</option><option>Remoto</option></select></div><div class="col-md-3"><label class="form-label">Contrato</label><select class="form-select" name="tipo_contrato"><option>Tiempo completo</option><option>Medio tiempo</option><option>Temporal</option><option>Práctica</option></select></div><div class="col-md-4"><label class="form-label">Salario</label><input class="form-control" type="number" name="salario"></div><div class="col-12"><label class="form-label">Descripción</label><textarea class="form-control" name="descripcion" rows="4" required></textarea></div><div class="col-12"><label class="form-label">Requisitos</label><textarea class="form-control" name="requisitos" rows="3"></textarea></div></div>
